function mostrarBoasVindas(){alert("Bem-vindo à loja TurboKids! Divirta-se!")}window.addEventListener("load",mostrarBoasVindas),document.addEventListener("DOMContentLoaded",function(){var e=document.querySelector("form");e&&e.addEventListener("submit",function(e){var t=document.querySelector("#nome"),o=document.querySelector("#email"),r=document.querySelector("#mensagem");t.value.trim()&&o.value.trim()&&r.value.trim()?alert("Mensagem enviada com sucesso!"):(alert("Por favor, preencha todos os campos antes de enviar."),e.preventDefault())})});let produtos=document.querySelectorAll(".produto");produtos.forEach(e=>{e.addEventListener("mouseenter",()=>{e.style.transform="scale(1.05)",e.style.transition="transform 0.3s ease"}),e.addEventListener("mouseleave",()=>{e.style.transform="scale(1)"})});